def create_code(words):
    if len(words) == 1:
        return words[0][:4].upper()
    elif len(words) == 2:
        return (words[0][:2] + words[1][:2]).upper()
    elif len(words) == 3:
        return (words[0][0] + words[1][0] + words[2][:2]).upper()
    elif len(words) == 4:
        return (words[0][0] + words[1][0] + words[2][0] + words[3][0]).upper()
    else:
        return ''

def bird_code(arr):
    codes = []
    for name in arr:
        words = name.replace('-', ' ').split()
        if len(words) == 1:
            code = words[0][:4].upper()
        elif len(words) == 2:
            code = words[0][:2] + words[1][:2].upper()
        elif len(words) == 3:
            code = words[0][0] + words[1][0] + words[2][:2].upper()
        elif len(words) == 4:
            code = words[0][0] + words[1][0] + words[2][0] + words[3][0].upper()
        codes.append(code)
    return codes

