def count_hits(round_results, is_double_hit):
    hits = {'P1': 0, 'P2': 0}
    for result in round_results:
        for player, shots in result[0].items():
            for shot in shots:
                if shot == 'X':
                    hits[player] += 2 if is_double_hit else 1
    return hits

def calculate_total_score(round_scores):
    total_scores = {'P1': 0, 'P2': 0}
    for round_result, is_double_hit in round_scores:
        p1_hits = count_hits(round_result['P1'], is_double_hit)
        p2_hits = count_hits(round_result['P2'], is_double_hit)
        total_scores['P1'] += p1_hits
        total_scores['P2'] += p2_hits
    if total_scores['P1'] > total_scores['P2']:
        return 'Pete Wins!'
    elif total_scores['P1'] < total_scores['P2']:
        return 'Phil Wins!'
    else:
        return 'Draw!'

def determine_winner(total_scores):
    pete_score, phil_score = total_scores
    if pete_score > phil_score:
        return 'Pete Wins!'
    elif phil_score > pete_score:
        return 'Phil Wins!'
    else:
        return 'Draw!'

