def is_palindrome(s: str) -> bool:
    return s == s[::-1]

def count_mismatches(s: str) -> int:
    left, right = (0, len(s) - 1)
    mismatches = 0
    while left < right:
        if s[left] != s[right]:
            mismatches += 1
        left += 1
        right -= 1
    return mismatches

def solve(s: str) -> bool:
    return count_mismatches(s) <= 1

