    positions = {'C': x.find('C'), 'D': x.find('D'), 'm': x.find('m')}
    if positions['C'] == -1 or positions['D'] == -1 or positions['m'] == -1:
        return {'result': 'boring without all three'}
    cat_pos, dog_pos, mouse_pos = (positions['C'], positions['D'], positions['m'])
    if abs(mouse_pos - cat_pos) <= 5 and dog_pos < min(cat_pos, mouse_pos):
        return {'result': 'Caught!'}
    elif abs(mouse_pos - cat_pos) <= 5:
        return {'result': 'Protected!'}
    else:
        return {'result': 'Escaped!'}

