    if cat_pos > len(x) - 1 or dog_pos > len(x) - 1 or mouse_pos > len(x) - 1:
        return False
    if cat_pos == dog_pos or cat_pos == mouse_pos or dog_pos == mouse_pos:
        return False
    return True

